import React, { useState, useEffect } from 'react';
import { Github, Linkedin, Mail, Phone, ExternalLink, Briefcase, Code, Database, Cloud, Brain, ChevronDown, Download, Menu, X, ArrowRight, Sparkles, Zap, Target } from 'lucide-react';

// IMPORTANT: Move your profile.jpg from 'public' to 'src/assets/' for this to work
import profileImg from './assets/profile.jpg'; 

const Portfolio = () => {
  const [scrollY, setScrollY] = useState(0);
  const [activeSection, setActiveSection] = useState('hero');
  const [menuOpen, setMenuOpen] = useState(false);
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [isVisible, setIsVisible] = useState({});
  const [typedText, setTypedText] = useState('');
  const fullText = "AI & Machine Learning Engineer";

  useEffect(() => {
    const handleScroll = () => {
      setScrollY(window.scrollY);
      const sections = ['hero', 'about', 'experience', 'projects', 'skills', 'contact'];
      const current = sections.find(section => {
        const element = document.getElementById(section);
        if (element) {
          const rect = element.getBoundingClientRect();
          return rect.top <= 100 && rect.bottom >= 100;
        }
        return false;
      });
      if (current) setActiveSection(current);
    };

    const handleMouseMove = (e) => {
      setMousePosition({ x: e.clientX, y: e.clientY });
    };

    window.addEventListener('scroll', handleScroll);
    window.addEventListener('mousemove', handleMouseMove);
    
    return () => {
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('mousemove', handleMouseMove);
    };
  }, []);

  useEffect(() => {
    if (typedText.length < fullText.length) {
      setTimeout(() => {
        setTypedText(fullText.slice(0, typedText.length + 1));
      }, 100);
    }
  }, [typedText]);

  useEffect(() => {
    const observer = new IntersectionObserver(
      (entries) => {
        entries.forEach((entry) => {
          setIsVisible(prev => ({
            ...prev,
            [entry.target.id]: entry.isIntersecting
          }));
        });
      },
      { threshold: 0.1 }
    );

    document.querySelectorAll('[data-animate]').forEach((el) => {
      observer.observe(el);
    });

    return () => observer.disconnect();
  }, []);

  const projects = [
    {
      title: "Deep Farming",
      subtitle: "Crop Disease Surveillance with Deep Learning",
      description: "Smart farming solution using CNN models for crop disease detection with real-time predictions via Flask web app. Achieved 95%+ accuracy in disease classification.",
      tags: ["Python", "TensorFlow", "CNN", "Flask", "Computer Vision"],
      icon: "🌱",
      gradient: "from-green-500 to-emerald-600",
      metrics: { accuracy: "95%", models: "3", dataset: "50K+" }
    },
    {
      title: "Intelligent SQL-Gen",
      subtitle: "NLP to SQL via RAG Architecture",
      // MODIFIED: Added the short, high-impact sentences here
      description: "Engineered automated pipelines and a vector-based retrieval system to perform semantic schema-linking for natural language queries. Implemented rigorous evaluation frameworks to maximize SQL accuracy and eliminate hallucinations.",
      tags: ["Azure OpenAI", "LangChain", "FAISS", "Streamlit", "RAG"],
      icon: "💬",
      gradient: "from-blue-500 to-cyan-600",
      metrics: { accuracy: "92%", queries: "1000+", time: "-80%" }
    },
    {
      title: "HealthCare Guidance Navigator",
      subtitle: "Agentic AI for Clinical Guidance",
      description: "RAG-based healthcare chatbot with intelligent retrieval pipelines providing real-time clinical insights and decision support for medical professionals.",
      tags: ["Agentic AI", "ChromaDB", "LangGraph", "Azure OpenAI"],
      icon: "🏥",
      gradient: "from-pink-500 to-rose-600",
      metrics: { users: "500+", accuracy: "94%", queries: "5K+" }
    }
  ];

  const skills = [
    { category: "Machine Learning", items: ["Linear/Logistic Regression", "Random Forest", "XGBoost"], icon: <Brain className="w-6 h-6" />, color: "purple" },
    { category: "Generative AI", items: ["RAG", "Prompt Engineering", "Vector DBs", "Embeddings"], icon: <Sparkles className="w-6 h-6" />, color: "pink" },
    { category: "Cloud & DevOps", items: ["AWS", "Azure OpenAI", "Docker", "CI/CD"], icon: <Cloud className="w-6 h-6" />, color: "blue" },
    { category: "Data & Databases", items: ["SQL", "Pandas", "NumPy", "FAISS", "ChromaDB"], icon: <Database className="w-6 h-6" />, color: "cyan" },
    { category: "Deep Learning", items: ["TensorFlow", "PyTorch", "CNN", "Transformers"], icon: <Zap className="w-6 h-6" />, color: "yellow" },
    { category: "Agentic AI", items: ["LangChain", "LangGraph", "CrewAI", "Multi-agent"], icon: <Target className="w-6 h-6" />, color: "green" }
  ];

  const experience = {
    company: "Vcitysoft Pvt.Ltd",
    role: "AI & ML Intern",
    duration: "6 Months",
    highlights: [
      "Developed end-to-end AI solutions across financial and healthcare domains",
      "Built scalable Python applications using Flask and OOP principles",
      "Implemented data visualization and statistical analysis pipelines",
      "Utilized AWS and Azure cloud platforms for deployment"
    ]
  };

  return (
    <div className="bg-black text-white min-h-screen overflow-x-hidden">
      {/* Custom Cursor */}
      <div 
        className="fixed w-6 h-6 border-2 border-purple-500 rounded-full pointer-events-none z-50 mix-blend-difference transition-transform duration-100"
        style={{ left: `${mousePosition.x}px`, top: `${mousePosition.y}px`, transform: 'translate(-50%, -50%)' }}
      />

      {/* Navigation */}
      <nav className="fixed top-0 w-full z-50 backdrop-blur-xl bg-black/50 border-b border-white/10">
        <div className="max-w-7xl mx-auto px-6 py-4 flex justify-between items-center">
          <div className="text-2xl font-bold">
            <span className="bg-gradient-to-r from-purple-400 via-pink-400 to-blue-400 bg-clip-text text-transparent">RH</span>
          </div>
          <div className="hidden md:flex gap-8 items-center">
            {['About', 'Experience', 'Projects', 'Skills', 'Contact'].map((item) => (
              <a key={item} href={`#${item.toLowerCase()}`} className={`relative hover:text-purple-400 transition-colors ${activeSection === item.toLowerCase() ? 'text-purple-400' : ''}`}>
                {item}
                {activeSection === item.toLowerCase() && <span className="absolute -bottom-1 left-0 w-full h-0.5 bg-gradient-to-r from-purple-400 to-blue-400"></span>}
              </a>
            ))}
          </div>
          <button className="md:hidden" onClick={() => setMenuOpen(!menuOpen)}>{menuOpen ? <X /> : <Menu />}</button>
        </div>
      </nav>

      {/* Hero Section */}
      <section id="hero" className="relative min-h-screen flex items-center justify-center px-6 pt-20">
        <div className="max-w-7xl mx-auto z-10 w-full">
          <div className="flex flex-col md:flex-row items-center justify-center gap-12 md:gap-16">
            
            {/* Profile Picture Fix */}
            <div className="flex-shrink-0">
              <div className="relative group cursor-pointer">
                <div className="absolute -inset-2 bg-gradient-to-r from-purple-600 via-pink-600 to-blue-600 rounded-full blur-2xl opacity-75 group-hover:opacity-100 transition duration-1000 animate-pulse"></div>
                <img 
                  src={profileImg} // MODIFIED: Uses imported image variable
                  alt="Rohit Harne"
                  className="relative w-64 h-64 md:w-80 md:h-80 rounded-full object-cover border-4 border-black shadow-2xl group-hover:scale-105 transition-transform duration-500"
                />
                <div className="absolute bottom-6 right-6 w-8 h-8 bg-green-500 rounded-full border-4 border-black animate-pulse"></div>
              </div>
            </div>

            <div className="flex-1 text-center md:text-left max-w-2xl">
              <h1 className="text-5xl md:text-7xl lg:text-8xl font-black mb-4 leading-tight">
                <span className="bg-gradient-to-r from-purple-400 via-pink-400 to-blue-400 bg-clip-text text-transparent animate-gradient">ROHIT HARNE</span>
              </h1>
              <div className="h-10 md:h-12 mb-6">
                <p className="text-xl md:text-3xl font-semibold text-transparent bg-clip-text bg-gradient-to-r from-gray-200 to-gray-400">
                  {typedText}<span className="animate-blink">|</span>
                </p>
              </div>
              <p className="text-base md:text-lg text-gray-400 mb-8 leading-relaxed">
                Crafting intelligent AI systems with <span className="text-purple-400 font-semibold">Deep Learning</span>, <span className="text-pink-400 font-semibold"> Generative AI</span>, and <span className="text-blue-400 font-semibold"> Agentic Workflows</span>.
              </p>
              <div className="flex gap-4 justify-center md:justify-start items-center flex-wrap mb-8">
                <a href="#projects" className="group flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-purple-600 to-blue-600 rounded-full hover:scale-105 transition-all font-semibold text-sm">
                  View My Work <ArrowRight className="w-4 h-4 group-hover:translate-x-1 transition-transform" />
                </a>
                <a href="#" className="flex items-center gap-2 px-6 py-3 border-2 border-white/20 rounded-full hover:bg-white/10 transition-all font-semibold text-sm">
                  <Download className="w-4 h-4" /> Download CV
                </a>
              </div>
            </div>
          </div>
        </div>
      </section>

      {/* Remaining Sections (Experience, Projects, etc.) ... */}
      {/* (I've kept the project rendering logic the same so it uses the updated 'projects' array above) */}
      
      <section id="projects" className="py-32 px-6">
        <div className="max-w-7xl mx-auto">
          <div className="text-center mb-20">
            <h2 className="text-5xl font-bold bg-gradient-to-r from-purple-400 to-blue-400 bg-clip-text text-transparent">Featured Projects</h2>
          </div>
          <div className="grid gap-8">
            {projects.map((project, idx) => (
              <div key={idx} className="group backdrop-blur-lg bg-white/5 rounded-3xl p-8 border border-white/10 hover:border-purple-500/50 transition-all">
                <div className="flex flex-col md:flex-row gap-8">
                  <div className={`w-24 h-24 bg-gradient-to-br ${project.gradient} rounded-2xl flex items-center justify-center text-5xl flex-shrink-0`}>
                    {project.icon}
                  </div>
                  <div className="flex-1">
                    <h3 className="text-3xl font-bold mb-2">{project.title}</h3>
                    <p className="text-gray-400 mb-4">{project.subtitle}</p>
                    <p className="text-gray-300 mb-6">{project.description}</p>
                    <div className="flex flex-wrap gap-2">
                      {project.tags.map((tag, i) => (
                        <span key={i} className="px-4 py-2 bg-white/5 border border-white/10 rounded-full text-sm">{tag}</span>
                      ))}
                    </div>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* Footer */}
      <footer className="py-12 px-6 border-t border-white/10 text-center">
        <p className="text-gray-400">© 2024 Rohit Harne. Crafted with 💜</p>
      </footer>

      {/* Styles */}
      <style>{`
        @keyframes gradient { 0%, 100% { background-position: 0% 50%; } 50% { background-position: 100% 50%; } }
        .animate-gradient { background-size: 200% 200%; animation: gradient 3s ease infinite; }
        .animate-blink { animation: blink 1s infinite; }
        @keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0; } }
      `}</style>
    </div>
  );
};

export default Portfolio;
